/* 共享流场让追兵绕开山庄建筑，避免大量敌人分别计算寻路。 */
const nav={w:58,h:42,minX:-29,minZ:-21,cell:1,walk:new Uint8Array(58*42),dist:new Int16Array(58*42),queue:new Int16Array(58*42),next:0};
for(let z=0;z<nav.h;z++)for(let x=0;x<nav.w;x++)nav.walk[z*nav.w+x]=isBlocked(x+nav.minX+.5,z+nav.minZ+.5,.52)?0:1;
function navIndex(x,z){return clamp(Math.floor(z-nav.minZ),0,nav.h-1)*nav.w+clamp(Math.floor(x-nav.minX),0,nav.w-1);}
function updateNavigation(){if(game.time<nav.next)return;nav.next=game.time+.65;nav.dist.fill(-1);let start=navIndex(game.player.x,game.player.z);if(!nav.walk[start]){const sx=start%nav.w,sz=Math.floor(start/nav.w);let best=1e9;for(let dz=-3;dz<=3;dz++)for(let dx=-3;dx<=3;dx++){const x=sx+dx,z=sz+dz;if(x<0||z<0||x>=nav.w||z>=nav.h)continue;const j=z*nav.w+x;if(nav.walk[j]&&dx*dx+dz*dz<best){best=dx*dx+dz*dz;start=j;}}}let head=0,tail=0;nav.queue[tail++]=start;nav.dist[start]=0;while(head<tail){const i=nav.queue[head++],x=i%nav.w,z=Math.floor(i/nav.w);for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dz)continue;const xx=x+dx,zz=z+dz;if(xx<0||zz<0||xx>=nav.w||zz>=nav.h)continue;const j=zz*nav.w+xx;if(!nav.walk[j]||nav.dist[j]>=0)continue;if(dx&&dz&&(!nav.walk[z*nav.w+xx]||!nav.walk[zz*nav.w+x]))continue;nav.dist[j]=nav.dist[i]+1;nav.queue[tail++]=j;}}}
function clearRoute(a,b){for(const o of obstacles){let near=0,far=1;for(const [v,d,min,max] of [[a.x,b.x-a.x,o.x-o.w-.5,o.x+o.w+.5],[a.z,b.z-a.z,o.z-o.d-.5,o.z+o.d+.5]]){if(Math.abs(d)<1e-6){if(v<min||v>max){near=2;break;}}else{let p=(min-v)/d,q=(max-v)/d;if(p>q)[p,q]=[q,p];near=Math.max(near,p);far=Math.min(far,q);if(near>far)break;}}if(near<=far&&far>=0&&near<=1)return false;}return true;}
function chaseDirection(e){const p=game.player;if(clearRoute(e,p))return{x:p.x-e.x,z:p.z-e.z};const i=navIndex(e.x,e.z),x=i%nav.w,z=Math.floor(i/nav.w);let best=1e9,target=null;for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dz)continue;const xx=x+dx,zz=z+dz;if(xx<0||zz<0||xx>=nav.w||zz>=nav.h)continue;const j=zz*nav.w+xx;if(!nav.walk[j]||nav.dist[j]<0)continue;if(dx&&dz&&(!nav.walk[z*nav.w+xx]||!nav.walk[zz*nav.w+x]))continue;const px=xx+nav.minX+.5,pz=zz+nav.minZ+.5,score=nav.dist[j]+Math.hypot(px-e.x,pz-e.z)*.12;if(score<best){best=score;target={x:px-e.x,z:pz-e.z};}}return target||{x:p.x-e.x,z:p.z-e.z};}
const rainGeo=new T.BufferGeometry(),rainArray=new Float32Array(550*6);for(let i=0;i<550;i++){const x=rand(-37,37),y=rand(0,23),z=rand(-30,30);rainArray.set([x,y,z,x-.08,y-.65,z+.05],i*6);}rainGeo.setAttribute('position',new T.BufferAttribute(rainArray,3));const rain=new T.LineSegments(rainGeo,new T.LineBasicMaterial({color:0xc9e7da,transparent:true,opacity:.18,depthWrite:false}));scene.add(rain);
function createHero(hero){const root=new T.Group(),rig=new T.Group();root.add(rig);const robe=material(hero.id==='sword'?0xc8d5bd:hero.id==='dagger'?0x535365:0xdac5a5),dark=material(hero.id==='sword'?0x456f65:hero.id==='dagger'?0x363644:0x68836b),skin=material(0xd9b89b),hair=material(0x252e2a);const body=part(rig,new T.ConeGeometry(.37,.92,8),robe,0,.78,0);body.rotation.y=Math.PI/8;cyl(rig,.27,.31,.45,hero.id==='sword'?0xadc2b0:hero.id==='dagger'?0x56536b:0xd0bd9c,0,1.17,0);box(rig,.56,.09,.4,0x927b50,0,1.04,0);part(rig,new T.SphereGeometry(.22,10,8),skin,0,1.62,0);part(rig,new T.SphereGeometry(.23,10,8),hair,0,1.7,.035);box(rig,.34,.11,.08,0x272e29,0,1.7,-.18);cyl(rig,.08,.11,.16,0x282e27,0,1.94,.04);const ribbon=box(rig,.035,.05,.52,hero.hex,.04,1.91,.23);ribbon.rotation.x=-.3;
 const legs=[];for(const x of [-.15,.15]){const leg=new T.Group();leg.position.set(x,.5,0);cyl(leg,.085,.07,.42,0x394a40,0,-.17,0);box(leg,.15,.12,.25,0x293a32,0,-.39,-.04);rig.add(leg);legs.push(leg);}const arms=[];for(const side of [-1,1]){const arm=new T.Group();arm.position.set(side*.29,1.31,0);const sleeve=part(arm,new T.ConeGeometry(.145,.52,6),dark,side*.1,-.18,0);sleeve.rotation.z=side*.3;part(arm,new T.SphereGeometry(.085,6,5),skin,side*.14,-.43,-.04);rig.add(arm);arms.push(arm);}
 const weapon=new T.Group();arms[1].add(weapon);weapon.position.set(.14,-.42,-.03);
 if(hero.id==='sword'){box(weapon,.075,.055,1.16,0xc2dbd4,0,0,-.5);box(weapon,.28,.07,.07,0xc7b272,0,0,0);box(weapon,.065,.065,.24,0x546b53,0,0,.15);}
 if(hero.id==='dagger'){for(const [arm,side] of [[arms[0],-1],[arms[1],1]]){box(arm,.07,.06,.58,0xc7c6dc,side*.14,-.44,-.3);box(arm,.18,.07,.06,0x9c8ab0,side*.14,-.43,-.04);}}
 if(hero.id==='healer'){cyl(weapon,.025,.025,1.25,0x8c8359,0,.45,0);const canopy=part(weapon,new T.ConeGeometry(.8,.25,10),new T.MeshStandardMaterial({color:0xd5b793,side:T.DoubleSide,roughness:.6}),0,1.15,0);for(let i=0;i<10;i++){const a=i/10*TAU;const rib=box(weapon,.025,.025,.78,0x8e7d58,Math.sin(a)*.38,1.12,Math.cos(a)*.38,a);rib.rotation.x=.1;}}
 const aura=part(root,new T.RingGeometry(.44,.49,32),new T.MeshBasicMaterial({color:hero.hex,transparent:true,opacity:.7,side:T.DoubleSide,depthWrite:false}),0,.045,0,-Math.PI/2);const shadow=part(root,new T.CircleGeometry(.5,24),new T.MeshBasicMaterial({color:0x071b15,transparent:true,opacity:.35,depthWrite:false}),0,.025,0,-Math.PI/2);shadow.castShadow=false;scene.add(root);return{root,rig,arms,legs,weapon,aura};}
