const effects=[],projectiles=[],enemyShots=[],pickups=[],areas=[],events=[],warnings=[];
const shared={blade:new T.BoxGeometry(.1,.07,.8),orb:new T.SphereGeometry(.11,6,5),ring:new T.RingGeometry(.94,1,40),disc:new T.CircleGeometry(1,40),gem:new T.OctahedronGeometry(.11),spark:new T.SphereGeometry(.06,5,4)};
const glowCache=new Map();function glow(color,opacity=.9){const key=color+'/'+opacity;if(!glowCache.has(key))glowCache.set(key,new T.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false,side:T.DoubleSide}));return glowCache.get(key);}
function fx(x,z,color,r=1,duration=.4,kind='ring'){if(effects.length>180)return;const mesh=new T.Mesh(kind==='disc'?shared.disc:shared.ring,glow(color,.55).clone());mesh.rotation.x=-Math.PI/2;mesh.position.set(x,.08,z);mesh.scale.setScalar(.2);scene.add(mesh);effects.push({mesh,t:0,d:duration,r,kind});}
function beam(a,b,color,width=.04,duration=.18){if(effects.length>180)return;const dx=b.x-a.x,dz=b.z-a.z,length=Math.hypot(dx,dz);const m=new T.Mesh(new T.BoxGeometry(width,.05,length),glow(color).clone());m.position.set((a.x+b.x)/2,.75,(a.z+b.z)/2);m.rotation.y=Math.atan2(dx,dz);scene.add(m);effects.push({mesh:m,t:0,d:duration,r:1,beam:true,ownGeo:true});}
function clearMesh(m,ownGeo=false,ownMat=false){scene.remove(m);if(ownGeo)m.geometry.dispose();if(ownMat)m.material.dispose();}
function audioInit(){if(audio)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const master=ctx.createGain();master.gain.value=soundOn?.16:0;master.connect(ctx.destination);const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.22;const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),ambient=ctx.createGain();source.buffer=buffer;source.loop=true;filter.type='lowpass';filter.frequency.value=2400;ambient.gain.value=.4;source.connect(filter);filter.connect(ambient);ambient.connect(master);source.start();audio={ctx,master,last:0,ambient};}catch{} }
function sound(kind){if(!soundOn||!audio)return;const {ctx,master}=audio,now=ctx.currentTime;if(kind==='hit'&&now-audio.last<.06)return;if(kind==='hit')audio.last=now;const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(master);let f=kind==='level'?660:kind==='dash'?320:kind==='ult'?150:kind==='hurt'?95:kind==='kill'?420:kind==='fusion'?440:750;let d=kind==='fusion'?1:kind==='ult'?.7:kind==='level'?.35:.12;o.type=kind==='hurt'?'triangle':'sine';o.frequency.setValueAtTime(f,now);o.frequency.exponentialRampToValueAtTime(kind==='level'||kind==='fusion'?f*2:f*.35,now+d);g.gain.setValueAtTime(.001,now);g.gain.exponentialRampToValueAtTime(kind==='ult'?.7:.3,now+.015);g.gain.exponentialRampToValueAtTime(.001,now+d);o.start(now);o.stop(now+d+.02);}
function saveRecord(){record.sound=soundOn;try{localStorage.setItem('yujian.v1',JSON.stringify(record))}catch{}}
function toast(text,duration=3){$('toast').textContent=text;$('toast').classList.add('visible');toastTimer=duration;}
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h);const size=w<720?17:14.5;camera.left=-size*w/h;camera.right=size*w/h;camera.top=size;camera.bottom=-size;camera.updateProjectionMatrix();}
addEventListener('resize',resize);resize();

function levelOf(id){return game?.skills[id]||0;}
function multiplier(){return 1+levelOf('aura')*.08;}
function rangeScale(){return 1+levelOf('aura')*.12;}
function maxHealth(){return game.hero.hp+levelOf('breath')*18;}
function isBlocked(x,z,pad=.35){return obstacles.some(o=>Math.abs(x-o.x)<o.w+pad&&Math.abs(z-o.z)<o.d+pad);}
function moveEntity(e,dx,dz,pad=.35){const limitX=29,limitZ=21;const nx=clamp(e.x+dx,-limitX,limitX),nz=clamp(e.z+dz,-limitZ,limitZ);if(!isBlocked(nx,e.z,pad))e.x=nx;if(!isBlocked(e.x,nz,pad))e.z=nz;}
function nearest(x,z,max=30,prefer=false){let target=null,dist=max*max;for(const e of game.enemies){if(e.dead)continue;let d=(e.x-x)**2+(e.z-z)**2;if(prefer&&(e.type==='elite'||e.type==='boss'))d*=.45;if(d<dist){dist=d;target=e;}}return target;}
function addProjectile(x,z,dx,dz,damage,options={}){if(projectiles.length>220)return;const len=Math.hypot(dx,dz)||1;const m=new T.Mesh(options.orb?shared.orb:shared.blade,glow(options.color||game.hero.hex));m.position.set(x,.9,z);m.rotation.y=Math.atan2(dx,dz);if(options.size)m.scale.setScalar(options.size);scene.add(m);projectiles.push({mesh:m,x,z,dx:dx/len,dz:dz/len,speed:options.speed||17,damage,life:options.life||.9,pierce:options.pierce||1,r:options.r||.42,hit:new Set(),...options});}
function fireFan(target,count,damage,options={}){const p=game.player;const angle=Math.atan2(target.x-p.x,target.z-p.z);for(let i=0;i<count;i++){const a=angle+(i-(count-1)/2)*(options.spread||.13);addProjectile(p.x,p.z,Math.sin(a),Math.cos(a),damage,options);}}
function addArea(x,z,r,damage,duration,color,type='damage'){if(areas.length>=45)return;const m=new T.Mesh(shared.disc,new T.MeshBasicMaterial({color,transparent:true,opacity:.12,depthWrite:false,side:T.DoubleSide}));m.rotation.x=-Math.PI/2;m.position.set(x,.055+areas.length*.0002,z);m.scale.setScalar(r);scene.add(m);areas.push({mesh:m,x,z,r,damage,life:duration,total:duration,tick:0,color,type});fx(x,z,color,r,.5);}
function damageArea(x,z,r,damage,options={}){for(const e of game.enemies){if(e.dead||Math.hypot(e.x-x,e.z-z)>r+e.r)continue;hitEnemy(e,damage,!!options.secondary);if(options.slow)e.slow=Math.max(e.slow,options.slow);if(options.push){const d=Math.hypot(e.x-x,e.z-z)||1;moveEntity(e,(e.x-x)/d*options.push,(e.z-z)/d*options.push,e.r);}}}
function hitEnemy(e,amount,secondary=false){if(e.dead)return;let damage=amount*multiplier();const critical=Math.random()<.08+levelOf('focus')*.08+(game.player.stealth>0?.55:0);if(critical)damage*=2;if(e.type==='shield')damage*=.8;e.hp-=damage;e.flash=.1;game.damage+=damage;game.hitCount++;if(!secondary&&game.fusion&&game.comboCD<=0){game.comboCD=.3;const f=game.fusion.id;if(f==='雷剑'){let next=null,best=36;for(const n of game.enemies){const d=(n.x-e.x)**2+(n.z-e.z)**2;if(n!==e&&!n.dead&&d<best){best=d;next=n;}}if(next){beam(e,next,0xa4ddff,.055,.22);hitEnemy(next,28+game.level*1.5,true);}fx(e.x,e.z,0xa4ddff,1.1,.2);}if(f==='冰剑'||f==='雪针'){e.slow=2;if(f==='雪针')game.player.shield=Math.min(40,game.player.shield+1.3);}if(f==='焚脉')e.burn=3;}
 if(e.hp<=0){e.dead=true;game.kills++;game.coins+=e.type==='boss'?100:e.type==='elite'?25:1;dropXp(e.x,e.z,ENEMY[e.type].xp);if(e.type==='elite'){game.tokens++;toast('剑使已退 · 获得一次悟道机会\n按 B 查阅绝学配方',4);sound('level');}if(e.type==='boss'){finish(true);return;}if(Math.random()<.018)dropXp(e.x+.2,e.z,0,true);}
}
function dropXp(x,z,value,heal=false){if(pickups.length>250){const oldest=pickups.shift();clearMesh(oldest.mesh);game.xp+=oldest.value*(1+levelOf('insight')*.15);}const m=new T.Mesh(shared.gem,glow(heal?0xeaa986:value>=50?0xe5cd8a:0x93cbb2));m.position.set(x,.2,z);if(value>=50||heal)m.scale.setScalar(1.8);scene.add(m);pickups.push({mesh:m,x,z,value,heal,born:game.time});}
function hurt(amount){const p=game.player;if(p.invuln>0||p.dashTime>0||state!=='playing')return;let left=amount;if(p.shield>0){const used=Math.min(left,p.shield);p.shield-=used;left-=used;}p.hp=Math.max(0,p.hp-left);p.invuln=.7;game.hurtFlash=.7;sound('hurt');if(p.hp<=0)finish(false);}
function heal(amount){const p=game.player,over=Math.max(0,p.hp+amount-maxHealth());p.hp=Math.min(maxHealth(),p.hp+amount);if(game.hero.id==='healer')p.shield=Math.min(40,p.shield+over);}
function doDash(){if(state!=='playing'||game.player.dash<1)return;const p=game.player;let dx=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+stick.x,dz=(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0)+stick.z;const len=Math.hypot(dx,dz);if(len<.1){dx=Math.sin(p.angle);dz=Math.cos(p.angle);}else{dx/=len;dz/=len;}p.dash--;p.dashTime=.2;p.dashX=dx;p.dashZ=dz;p.invuln=Math.max(p.invuln,.3);if(game.hero.id==='dagger'){p.stealth=2;if(levelOf('shadow'))game.skillTimers.shadow=0;if(game.fusion?.id==='叶影'){for(let i=0;i<8;i++){const a=i/8*TAU;addProjectile(p.x,p.z,Math.sin(a),Math.cos(a),55,{color:0xc8ef9e,pierce:5,life:.6});}}}fx(p.x,p.z,game.hero.hex,1,.35);sound('dash');}
function ultimate(){if(state!=='playing'||game.player.ult>0)return;const p=game.player;p.ult=22*(1-levelOf('energy')*.1);p.invuln=1.1;const f=game.fusion?.id,color=game.fusion?.color||game.hero.hex;fx(p.x,p.z,color,9*rangeScale(),1.1);sound('ult');toast(game.fusion?game.fusion.name:game.hero.ult,1.7);
 if(game.hero.id==='sword'){damageArea(p.x,p.z,9*rangeScale(),game.fusion?320:155,{slow:f==='冰剑'?4:0});for(let i=0;i<18;i++){const a=i/18*TAU;addProjectile(p.x,p.z,Math.sin(a),Math.cos(a),game.fusion?160:90,{color,pierce:9,life:1.1,speed:21,size:1.6});}if(f==='冰剑')addArea(p.x,p.z,7,45,5,color,'ice');if(f==='雷剑')for(const e of game.enemies){if(!e.dead&&Math.hypot(e.x-p.x,e.z-p.z)<12){beam(p,e,color,.08,.45);hitEnemy(e,90,true);}}}
 if(game.hero.id==='dagger'){const sorted=game.enemies.filter(e=>!e.dead).sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z)).slice(0,16);for(const e of sorted){beam(p,e,color,.09,.4);hitEnemy(e,game.fusion?380:200);if(f==='焚脉')addArea(e.x,e.z,1.7,45,3,color);}if(f==='叶影')for(let i=0;i<24;i++){const a=i/24*TAU;addProjectile(p.x,p.z,Math.sin(a),Math.cos(a),100,{color,pierce:6,life:1.1});}}
 if(game.hero.id==='healer'){heal(42);p.shield=Math.min(40,p.shield+18);addArea(p.x,p.z,7*rangeScale(),game.fusion?115:65,6,color,f==='雪针'?'ice':'heal');damageArea(p.x,p.z,7,90,{slow:f==='雪针'?4:0});if(f==='雪针'){for(let i=0;i<20;i++){const a=i/20*TAU;addProjectile(p.x,p.z,Math.sin(a),Math.cos(a),135,{color,pierce:6,life:1.3});}}}
}
function spawnEnemy(type,at=null){const pool=enemyPools[type];if(game.enemies.filter(e=>!e.dead&&e.type===type).length>=pool.max)return;let x,z;const p=game.player;for(let i=0;i<30;i++){if(at){x=at.x;z=at.z;}else{const a=rand(0,TAU),r=rand(16,23);x=clamp(p.x+Math.sin(a)*r,-28,28);z=clamp(p.z+Math.cos(a)*r,-20,20);}if(!isBlocked(x,z,.5)&&Math.hypot(x-p.x,z-p.z)>6)break;}if(isBlocked(x,z,.5))return;const def=ENEMY[type],special=type==='boss'||type==='elite',scale=type==='boss'?1.75:type==='elite'?1.45:type==='shield'?1.15:1;const hp=def.hp*(special?1:1+game.time/440);const e={id:++game.enemySerial,type,x,z,hp,maxHp:hp,r:special?.62:.32,speed:def.speed,damage:def.damage,angle:0,slow:0,burn:0,burnTick:0,flash:0,attack:rand(1,3),scale,dead:false,phase:0};game.enemies.push(e);if(type==='boss'){game.boss=e;$('boss-hud').classList.remove('hidden');toast('黑伞客现身\n晨钟将至，须在十分钟内破局',4);sound('ult');}if(type==='elite')toast('执令剑使入场 · 击败可获悟道机会',3);}
function warnCircle(x,z,r,damage,delay=1){const m=new T.Mesh(shared.disc,new T.MeshBasicMaterial({color:0xed785d,transparent:true,opacity:.19,side:T.DoubleSide,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(x,.07,z);m.scale.setScalar(r);scene.add(m);warnings.push({mesh:m,x,z,r,damage,t:delay,total:delay});}
function shootEnemy(e,count=1,speed=8){const p=game.player,angle=Math.atan2(p.x-e.x,p.z-e.z);for(let i=0;i<count;i++){const a=angle+(i-(count-1)/2)*.17;const m=new T.Mesh(shared.blade,glow(e.type==='boss'?0xf1a18e:0xe5a879));m.position.set(e.x,.8,e.z);m.rotation.y=a;scene.add(m);enemyShots.push({mesh:m,x:e.x,z:e.z,dx:Math.sin(a),dz:Math.cos(a),speed,life:4,damage:e.damage});}}
function updateEnemies(dt){const p=game.player;updateNavigation();let alive=0;for(const e of game.enemies){if(e.dead)continue;alive++;e.flash=Math.max(0,e.flash-dt);e.slow=Math.max(0,e.slow-dt);if(e.burn>0){e.burn-=dt;e.burnTick-=dt;if(e.burnTick<=0){e.burnTick=.5;hitEnemy(e,16,true);}}const dx=p.x-e.x,dz=p.z-e.z,d=Math.hypot(dx,dz)||1;e.angle=Math.atan2(dx,dz);e.attack-=dt;let movement=e.speed*(e.slow>0?.38:1);if(e.type==='archer'&&d<10&&clearRoute(e,p))movement=d<6?-movement*.6:0;if(e.type==='bomber'&&d<9)movement=0;if((e.type==='archer'||e.type==='bomber')&&e.attack<=0){e.attack=e.type==='archer'?2.6:3.8;if(e.type==='archer')shootEnemy(e);else warnCircle(p.x+p.vx*.35,p.z+p.vz*.35,2,e.damage,1.1);}
 if(e.type==='assassin'&&e.attack<=0&&d<10){e.attack=4;fx(e.x,e.z,0xc7aadf,1,.3);movement*=3;}
 if(e.type==='elite'&&e.attack<=0){e.attack=3;shootEnemy(e,5,7);warnCircle(p.x,p.z,2.5,20,1.25);}
 if(e.type==='boss'&&e.attack<=0){e.phase++;e.attack=e.hp<e.maxHp*.5?1.5:2.1;if(e.phase%3===0){for(let i=0;i<6;i++){const a=i/6*TAU;warnCircle(p.x+Math.sin(a)*3.8,p.z+Math.cos(a)*3.8,1.65,24,1.3);}}else if(e.phase%3===1)shootEnemy(e,9,7);else{warnCircle(p.x,p.z,3.2,30,1.1);for(let i=0;i<3;i++)spawnEnemy('assassin');}}
 const chase=movement>=0?chaseDirection(e):{x:dx,z:dz},length=Math.hypot(chase.x,chase.z)||1;moveEntity(e,chase.x/length*movement*dt,chase.z/length*movement*dt,e.r*.75);if(d<e.r+.45)hurt(e.damage);}
 if(game.time>game.nextSpawn&&alive<90){const t=game.time;let types=['blade'];if(t>35)types.push('archer');if(t>100)types.push('shield');if(t>160)types.push('bomber');if(t>220)types.push('assassin');if(t>300)types.push('lancer');const amount=t>400?3:t>170?2:1;for(let i=0;i<amount;i++)spawnEnemy(pick(types));game.nextSpawn=t+Math.max(.25,.65-t*.00065);}
 game.enemies=game.enemies.filter(e=>!e.dead);updateEnemyVisuals();
}
function updateEnemyVisuals(){for(const [type,pool] of Object.entries(enemyPools)){let i=0;for(const e of game?.enemies||[]){if(e.type!==type||e.dead||i>=pool.max)continue;const s=e.scale,bob=Math.sin((game.time*7+e.id))* .04;dummy.position.set(e.x,(.68+bob)*s,e.z);dummy.rotation.set(0,e.angle,0);dummy.scale.set(s,s,s);dummy.updateMatrix();pool.body.setMatrixAt(i,dummy.matrix);dummy.position.y=(1.34+bob)*s;dummy.updateMatrix();pool.head.setMatrixAt(i,dummy.matrix);dummy.position.y=(type==='boss'?1.72:1.51)*s;dummy.updateMatrix();pool.hat.setMatrixAt(i,dummy.matrix);dummy.position.set(e.x+Math.cos(e.angle)*.3*s,.87*s,e.z-Math.sin(e.angle)*.3*s);dummy.rotation.set(-.4,e.angle,0);dummy.updateMatrix();pool.arm.setMatrixAt(i,dummy.matrix);i++;}for(const m of [pool.body,pool.head,pool.hat,pool.arm]){m.count=i;m.instanceMatrix.needsUpdate=true;m.computeBoundingSphere();}}}
function autoAttack(){const p=game.player;let target=nearest(p.x,p.z,18);if(!target)return;if(pointer.active){const v=new T.Vector3(pointer.x,pointer.y,.5);const ray=new T.Raycaster();ray.setFromCamera({x:pointer.x,y:pointer.y},camera);const hit=new T.Vector3();if(ray.ray.intersectPlane(new T.Plane(new T.Vector3(0,1,0),0),hit)&&Math.hypot(hit.x-p.x,hit.z-p.z)>.5)target={x:hit.x,z:hit.z};}
 const lv=levelOf('weapon'),damage=game.hero.attack*(1+(lv-1)*.3)*(1+levelOf('energy')*.08),count=1+Math.floor(lv/3);p.angle=Math.atan2(target.x-p.x,target.z-p.z);p.swing=.2;game.shots++;const opts={color:game.fusion?.color||game.hero.hex,pierce:game.hero.id==='sword'?3+lv:game.hero.id==='healer'?2:2,life:game.hero.id==='dagger'?.43:.85,speed:game.hero.id==='dagger'?22:17};
 if(game.hero.id==='sword'){game.swordCount++;if(game.swordCount%8===0){opts.size=2;opts.pierce=12;fireFan(target,count+1,damage*1.8,opts);}else fireFan(target,count,damage,opts);}
 if(game.hero.id==='dagger'){fireFan(target,2+Math.floor(lv/3),damage,{...opts,spread:.18});if(game.fusion?.id==='叶影')fireFan(target,3,damage*.6,{color:0xc8ef9e,pierce:5,life:1.1,speed:19,spread:.3});}
 if(game.hero.id==='healer')fireFan(target,count+1,damage,{...opts,orb:true,spread:.2});sound('hit');
}
function castSkill(id,lv){const p=game.player,target=nearest(p.x,p.z,24,true),scale=rangeScale(),f=game.fusion?.id;const dmg=1+game.level*.025;
 switch(id){
 case'orbit':{const r=(2+lv*.5)*scale;fx(p.x,p.z,f==='雷剑'?0xa2d9ff:game.hero.hex,r,.48);damageArea(p.x,p.z,r,(22+lv*13)*dmg);for(let i=0;i<3+lv;i++){const a=i/(3+lv)*TAU+game.time;addProjectile(p.x+Math.sin(a)*1.8,p.z+Math.cos(a)*1.8,Math.cos(a),-Math.sin(a),28*lv,{color:game.hero.hex,pierce:4,life:.35});}break;}
 case'return':if(target){fireFan(target,1+lv,30*lv*dmg,{color:f==='冰剑'?0xa3eced:game.hero.hex,pierce:12,life:1.5,speed:12,boomerang:true});if(f==='冰剑')addArea(p.x,p.z,3.5,28,3,0xa3eced,'ice');}break;
 case'shadow':if(target){for(let i=0;i<lv+1;i++){const e=nearest(p.x+rand(-3,3),p.z+rand(-3,3),9);if(e){beam(p,e,0xc6b4e7,.065,.25);hitEnemy(e,40*lv*dmg);fx(e.x,e.z,0xc6b4e7,1,.25);}}}break;
 case'mark':if(target){fx(target.x,target.z,0xe0a0c6,2+lv*.4,.7);damageArea(target.x,target.z,2+lv*.4,50*lv*dmg);if(f==='焚脉')addArea(target.x,target.z,3,40,3,0xf5ac7a);}break;
 case'mist':addArea(p.x,p.z,(2.3+lv*.4)*scale*(f==='焚香'?1.25:1),15*lv*dmg*(f==='焚香'?1.65:1),4,f==='焚香'?0xf4b47f:0xbad3a1,f==='焚香'?'incense':'heal');break;
 case'needle':if(target)fireFan(target,3+lv*2,22*lv*dmg,{color:f==='雪针'?0xa3e4e8:0xe9ccac,pierce:3,speed:20,life:1.2,homing:true});break;
 case'thunder':if(target){const n=lv+1;const targets=game.enemies.filter(e=>!e.dead).sort((a,b)=>(a.x-target.x)**2+(a.z-target.z)**2-(b.x-target.x)**2-(b.z-target.z)**2).slice(0,n);for(const e of targets){beam({x:e.x-.35,z:e.z-.4},e,0xc6e5ff,.13,.24);fx(e.x,e.z,0xc6e5ff,1.3,.28);damageArea(e.x,e.z,1.3,32*lv*dmg);}}break;
 case'fire':if(target)addArea(target.x,target.z,(1.6+lv*.35)*scale,18*lv*dmg,3.5,0xf2ac7e);break;
 case'ice':fx(p.x,p.z,0xa7e2e2,(3+lv*.7)*scale,.7);damageArea(p.x,p.z,(3+lv*.7)*scale,24*lv*dmg,{slow:2.5});break;
 case'leaf':if(target)fireFan(target,3+lv,20*lv*dmg,{color:0xbadf9e,pierce:6,life:1.1,spread:.23});break;
 case'wind':fx(p.x,p.z,0xe0e6c5,(2.5+lv*.5)*scale,.4);damageArea(p.x,p.z,(2.5+lv*.5)*scale,22*lv*dmg,{push:2.2});break;
 case'petal':if(target){const x=target.x,z=target.z;addArea(x,z,(2+lv*.45)*scale,25*lv*dmg,2.2,0xe7b1c8);fx(x,z,0xe7b1c8,3,.8);}break;
 }
}
const skillCD={orbit:1.5,return:2.4,shadow:2,mark:3.8,mist:3.7,needle:2.1,thunder:3,fire:3.2,ice:3.8,leaf:2.3,wind:3.4,petal:3.6};
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const b=projectiles[i];b.life-=dt;if(b.boomerang&&b.life<.7){const dx=game.player.x-b.x,dz=game.player.z-b.z,l=Math.hypot(dx,dz)||1;b.dx=dx/l;b.dz=dz/l;}if(b.homing){const e=nearest(b.x,b.z,8);if(e){const dx=e.x-b.x,dz=e.z-b.z,l=Math.hypot(dx,dz)||1;b.dx+=(dx/l-b.dx)*dt*5;b.dz+=(dz/l-b.dz)*dt*5;}}b.x+=b.dx*b.speed*dt;b.z+=b.dz*b.speed*dt;b.mesh.position.set(b.x,.85,b.z);b.mesh.rotation.y=Math.atan2(b.dx,b.dz);for(const e of game.enemies){if(e.dead||b.hit.has(e.id)||Math.hypot(b.x-e.x,b.z-e.z)>b.r+e.r)continue;b.hit.add(e.id);hitEnemy(e,b.damage);b.pierce--;if(b.pierce<=0){b.life=0;break;}}if(b.life<=0){clearMesh(b.mesh);projectiles.splice(i,1);}}
 for(let i=enemyShots.length-1;i>=0;i--){const b=enemyShots[i];b.life-=dt;b.x+=b.dx*b.speed*dt;b.z+=b.dz*b.speed*dt;b.mesh.position.set(b.x,.75,b.z);if(Math.hypot(b.x-game.player.x,b.z-game.player.z)<.43){hurt(b.damage);b.life=0;}if(b.life<=0||isBlocked(b.x,b.z,.05)){clearMesh(b.mesh);enemyShots.splice(i,1);}}
}
function updateAreas(dt){for(let i=areas.length-1;i>=0;i--){const a=areas[i];a.life-=dt;a.tick-=dt;a.mesh.material.opacity=.1+.045*Math.sin(game.time*5);if(a.tick<=0){a.tick=.5;damageArea(a.x,a.z,a.r,a.damage*.5,{secondary:true,slow:a.type==='ice'?1:0});if((a.type==='heal'||a.type==='incense')&&Math.hypot(a.x-game.player.x,a.z-game.player.z)<a.r)heal(a.type==='incense'?2.8:1.8);}if(a.life<=0){clearMesh(a.mesh,false,true);areas.splice(i,1);}}
 for(let i=warnings.length-1;i>=0;i--){const w=warnings[i];w.t-=dt;w.mesh.material.opacity=.15+(1-w.t/w.total)*.32;if(w.t<=0){fx(w.x,w.z,0xed785d,w.r,.4);if(Math.hypot(w.x-game.player.x,w.z-game.player.z)<w.r)hurt(w.damage);clearMesh(w.mesh,false,true);warnings.splice(i,1);}}
}
function updatePickups(dt){const p=game.player,magnet=2.6+levelOf('insight')*1.25;for(let i=pickups.length-1;i>=0;i--){const g=pickups[i],d=Math.hypot(g.x-p.x,g.z-p.z);if(d<magnet||game.time-g.born>25){const speed=dt*(8+magnet);g.x+=(p.x-g.x)/Math.max(d,.1)*Math.min(speed,d);g.z+=(p.z-g.z)/Math.max(d,.1)*Math.min(speed,d);}g.mesh.position.set(g.x,.22+Math.sin(game.time*3+i)*.05,g.z);g.mesh.rotation.y+=dt;if(d<.7){if(g.heal){heal(20);fx(p.x,p.z,0xd0e8af,1,.3);}else game.xp+=g.value*(1+levelOf('insight')*.15);clearMesh(g.mesh);pickups.splice(i,1);}}
 if(game.xp>=game.need&&state==='playing'){game.xp-=game.need;game.level++;game.need=20+game.level*6+game.level*game.level*.8;heal(5);sound('level');openUpgrade();}
}
function updatePlayer(dt){const p=game.player;p.invuln=Math.max(0,p.invuln-dt);p.stealth=Math.max(0,p.stealth-dt);p.dashTime=Math.max(0,p.dashTime-dt);p.ult=Math.max(0,p.ult-dt);p.dash=Math.min(2,p.dash+dt/(4.5-levelOf('speed')*.5));p.swing=Math.max(0,p.swing-dt);game.comboCD=Math.max(0,game.comboCD-dt);let dx=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+stick.x,dz=(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0)+stick.z;const len=Math.hypot(dx,dz);if(len>1){dx/=len;dz/=len;}const speed=game.hero.speed*(1+levelOf('speed')*.08);p.vx=dx*speed;p.vz=dz*speed;if(p.dashTime>0){p.vx=p.dashX*25;p.vz=p.dashZ*25;}moveEntity(p,p.vx*dt,p.vz*dt,.28);p.attack-=dt;if(p.attack<=0){p.attack=game.hero.rate/(1+(levelOf('weapon')-1)*.06);autoAttack();}
 for(const [id,lv] of Object.entries(game.skills)){if(!skillCD[id])continue;game.skillTimers[id]=(game.skillTimers[id]??rand(.2,1))-dt;if(game.skillTimers[id]<=0){game.skillTimers[id]=skillCD[id]*(1-(lv-1)*.08);castSkill(id,lv);}}
 if(game.hero.id==='healer'){game.healTimer-=dt;if(game.healTimer<=0){game.healTimer=6;heal(5);fx(p.x,p.z,0xd2dfaf,1.2,.5);}}
 heroVisual.root.position.set(p.x,p.dashTime>0?Math.sin(p.dashTime/.2*Math.PI)*.65:0,p.z);heroVisual.rig.rotation.y=p.angle;const walk=Math.sin(game.time*13)*Math.min(1,len)*.45;heroVisual.legs[0].rotation.x=walk;heroVisual.legs[1].rotation.x=-walk;heroVisual.arms[0].rotation.x=-walk*.6;heroVisual.arms[1].rotation.x=p.swing>0?-.8:walk*.5;heroVisual.rig.rotation.z=p.dashTime>0?-.15:0;heroVisual.aura.rotation.z+=dt*.4;heroVisual.root.visible=!(p.invuln>0&&Math.floor(game.time*20)%2===0&&p.dashTime<=0);}
function createEvents(){const defs=[{id:'scholar',name:'桥边老叟',glyph:'悟',x:12,z:0,color:0xd3c28c},{id:'medic',name:'负伤侠客',glyph:'援',x:-13,z:9,color:0xa8d1b0},{id:'merchant',name:'游方货郎',glyph:'商',x:3,z:-11,color:0xd6b686}];for(const e of defs){const root=new T.Group();cyl(root,.3,.4,.9,0x8b9a7d,0,.6,0);cyl(root,.16,.16,.3,0xc0b69a,0,1.25,0);const ring=part(root,new T.RingGeometry(.8,.85,32),glow(e.color,.6),0,.03,0,-Math.PI/2);const orb=part(root,new T.OctahedronGeometry(.16),glow(e.color),0,2.1,0);root.position.set(e.x,0,e.z);scene.add(root);events.push({...e,root,ring,orb,used:false});}}
function updateEvents(dt){let near=null;for(const e of events){e.orb.position.y=2.1+Math.sin(game.time*2)*.12;e.ring.rotation.z+=dt*.5;if(!e.used&&Math.hypot(e.x-game.player.x,e.z-game.player.z)<2)near=e;}if(near){if(game.nearEvent!==near){game.nearEvent=near;game.eventHold=0;toast(`${near.name} · 按 E 交谈\n也可停步片刻，听一段江湖事`,3);}game.eventHold=Math.hypot(game.player.vx,game.player.vz)<.2?game.eventHold+dt:0;if(keys.has('KeyE')||game.eventHold>1.6){keys.delete('KeyE');openEvent(near);}}else{game.nearEvent=null;game.eventHold=0;}}
function updateGame(dt){game.time+=dt;if(game.time>=600){finish(false,true);return;}if(!game.elite1&&game.time>=240){game.elite1=true;spawnEnemy('elite');}if(!game.elite2&&game.time>=420){game.elite2=true;spawnEnemy('elite');}if(!game.bossSpawned&&game.time>=510){game.bossSpawned=true;spawnEnemy('boss');}updatePlayer(dt);if(state!=='playing')return;updateEnemies(dt);if(state!=='playing')return;updateProjectiles(dt);if(state!=='playing')return;updateAreas(dt);updatePickups(dt);if(state!=='playing')return;updateEvents(dt);game.hurtFlash=Math.max(0,game.hurtFlash-dt*2);$('damage-flash').style.opacity=game.hurtFlash*.65;}

const categoryNames={weapon:'专属兵器',exclusive:'门派武学',common:'江湖武学',passive:'内功心法'};
function showModal(html,mode){state=mode;keys.clear();stick.x=stick.z=0;$('modal-content').innerHTML=html;$('modal').classList.remove('hidden');const focus=$('modal-content').querySelector('button:not(:disabled)');if(focus)focus.focus({preventScroll:true});}
function closeModal(){state=game?'playing':'home';$('modal').classList.add('hidden');keys.clear();last=performance.now();}
function skillName(id){return id==='weapon'?game.hero.weapon:SKILLS[id].name;}
function ownedType(type){return Object.keys(game.skills).filter(id=>SKILLS[id].type===type).length;}
function upgradePool(){const result=[];for(const [id,def] of Object.entries(SKILLS)){if(def.type==='exclusive'&&!game.hero.exclusive.includes(id))continue;const lv=levelOf(id);if(lv>=def.max)continue;if(lv===0&&((def.type==='common'&&ownedType('common')>=3)||(def.type==='passive'&&ownedType('passive')>=3)))continue;let weight=lv>0?2:1;if(def.type==='weapon')weight=3;if(def.type==='exclusive')weight=3;const recipe=RECIPES.filter(r=>r.hero===game.hero.id);if(recipe.some(r=>r.common===id&&levelOf(r.skill)>0))weight+=2;result.push({id,weight});}return result;}
function chooseUpgrades(){let pool=upgradePool(),result=[];for(let i=0;i<3&&pool.length;i++){let sum=pool.reduce((a,b)=>a+b.weight,0),v=Math.random()*sum,idx=0;for(;idx<pool.length-1;idx++){v-=pool[idx].weight;if(v<=0)break;}result.push(pool[idx].id);pool.splice(idx,1);}if(game.level<=3&&levelOf('weapon')<3&&!result.includes('weapon'))result[0]='weapon';if(game.level===4&&!game.hero.exclusive.some(id=>levelOf(id)>0))result[0]=game.hero.exclusive[0];return result;}
function upgradeDescription(id){const lv=levelOf(id)+1;if(id==='weapon')return `兵器提升至第${roman[lv]}重，伤害增加30%。${lv===3||lv===6?'额外增加一道攻击。':'六重可参悟融合绝学。'}`;return SKILLS[id].desc+(SKILLS[id].type==='passive'?'':lv>1?' 本重进一步提高威力与效率。':'');}
function openUpgrade(){game.choices=chooseUpgrades();if(!game.choices.length){heal(20);game.coins+=20;return;}renderUpgrade();}
function renderUpgrade(){const cards=game.choices.map((id,i)=>{const d=SKILLS[id],lv=levelOf(id);return `<button class="upgrade-card" data-upgrade="${id}" style="--card-color:${d.color}"><span class="category">${categoryNames[d.type]}</span><span class="rank">${lv?`${roman[lv]} → ${roman[lv+1]}重`:'初习'}</span><span class="big-symbol">${id==='weapon'?game.hero.glyph:d.glyph}</span><b>${skillName(id)}</b><p>${upgradeDescription(id)}</p></button>`;}).join('');showModal(`<section class="modal-panel"><div class="modal-eyebrow">领悟 · 第 ${game.level} 重境界</div><h2 class="modal-title">此刻，习得一式</h2><p class="modal-sub">择一门武学带入此局。门派武学与江湖武学修成之后，可参悟融合绝学。</p><div class="upgrade-grid">${cards}</div><div class="modal-actions"><span class="note">时间已暂停 · 可按 1 / 2 / 3 选择</span><button class="secondary" id="reroll" ${game.rerolls<=0?'disabled':''}>重阅秘籍 · 余 ${game.rerolls} 次</button></div></section>`,'upgrade');$('modal-content').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>selectUpgrade(b.dataset.upgrade));$('reroll').onclick=()=>{if(game.rerolls>0){game.rerolls--;game.choices=chooseUpgrades();renderUpgrade();}};}
function gainSkill(id){if(levelOf(id)>=SKILLS[id].max)return false;game.skills[id]=levelOf(id)+1;game.skillTimers[id]=.1;if(id==='breath')heal(25);if(id==='energy')game.player.ult=Math.max(0,game.player.ult-2);return true;}
function selectUpgrade(id){if(state!=='upgrade'||!game.choices.includes(id))return;gainSkill(id);closeModal();updateHUD();const ready=availableRecipes();if(ready.length){openBook(true);}else{toast(`${skillName(id)} · 第${roman[levelOf(id)]}重`,1.5);}}
function availableRecipes(){if(!game||game.fusion||game.tokens<1)return[];return RECIPES.filter(r=>r.hero===game.hero.id&&levelOf('weapon')>=6&&levelOf(r.skill)>=3&&levelOf(r.common)>=3);}
function openBook(ready=false){if(!game||!['playing','paused','book','upgrade'].includes(state))return;const recipes=RECIPES.filter(r=>r.hero===game.hero.id),can=availableRecipes();const cards=recipes.map(r=>{const met=[levelOf('weapon')>=6,levelOf(r.skill)>=3,levelOf(r.common)>=3,game.tokens>0];const owned=game.fusion?.id===r.id;return `<article class="recipe"><h3>${r.name}${owned?' · 已修成':''}</h3><p>${r.desc}</p><div class="requirements"><span class="${met[0]?'met':''}">${game.hero.weapon} ${levelOf('weapon')}/6</span><span class="${met[1]?'met':''}">${SKILLS[r.skill].name} ${levelOf(r.skill)}/3</span><span class="${met[2]?'met':''}">${SKILLS[r.common].name} ${levelOf(r.common)}/3</span><span class="${met[3]?'met':''}">悟道机会 ${game.tokens}/1</span></div><button class="secondary" data-fusion="${r.id}" ${can.includes(r)?'':'disabled'}>${owned?'此局已修成':game.fusion?'每局限修一门绝学':met.every(Boolean)?'参悟此门绝学':'尚需修习'}</button></article>`;}).join('');showModal(`<section class="modal-panel"><div class="modal-eyebrow">归元录 · ${game.hero.sect}</div><h2 class="modal-title">${ready?'灵光乍现，可悟绝学':'武学有路，融会贯通'}</h2><p class="modal-sub">兵器六重、对应武学各三重，消耗一次悟道机会。击败四分钟与七分钟出现的剑使，可获得悟道机会。</p><div class="recipe-grid">${cards}</div><div class="owned-list">当前内功：${Object.keys(game.skills).filter(id=>SKILLS[id].type==='passive').map(id=>`${SKILLS[id].name} ${roman[levelOf(id)]}重`).join(' · ')||'尚未习得'}<br>通用武学 ${ownedType('common')}/3 · 内功心法 ${ownedType('passive')}/3 · 悟道机会 ${game.tokens}</div><div class="modal-actions"><span class="note">时间已暂停 · 此局只能修成一门融合绝学</span><button class="secondary" id="book-close">合卷，继续行走 · B</button></div></section>`,'book');$('book-close').onclick=closeModal;$('modal-content').querySelectorAll('[data-fusion]').forEach(b=>b.onclick=()=>{const r=availableRecipes().find(r=>r.id===b.dataset.fusion);if(!r)return;game.tokens--;game.fusion=r;closeModal();game.player.ult=0;fx(game.player.x,game.player.z,r.color,10,1.5);sound('fusion');toast(`绝学已成 · ${r.name}\nQ 绝技已就绪`,5);updateHUD();});}
function openEvent(e){if(state!=='playing'||e.used)return;e.used=true;e.root.visible=false;let title,desc,choices;
 if(e.id==='scholar'){title='桥边听雨，老叟授艺';desc='“招式各有来处，气却同归一源。”老叟指向你手中的残卷，愿传你一式本门武学。';const candidates=game.hero.exclusive.filter(id=>levelOf(id)<3);choices=candidates.length?candidates.map(id=>({name:`研习 · ${SKILLS[id].name}`,desc:SKILLS[id].desc,action:()=>gainSkill(id)})):[{name:'温故知新',desc:'恢复30生命，并获得一次重阅秘籍的机会。',action:()=>{heal(30);game.rerolls++;}}];}
 if(e.id==='medic'){title='江湖有义，援手相助';desc='受伤的侠客递来一只药囊：“今夜能走出去的人，总该带点好消息。”';choices=[{name:'接过伤药',desc:'恢复50生命，并获得15护盾。',action:()=>{heal(50);game.player.shield=Math.min(40,game.player.shield+15);}},{name:'请教脱身之法',desc:levelOf('speed')<3&&(levelOf('speed')>0||ownedType('passive')<3)?'获得一重疾行诀。':'获得两次重阅秘籍的机会。',action:()=>{if(levelOf('speed')<3&&(levelOf('speed')>0||ownedType('passive')<3))gainSkill('speed');else game.rerolls+=2;}}];}
 if(e.id==='merchant'){title='灯下货郎，秘籍待价';desc=`“钱财身外物，活着才能花。”你此刻有 ${game.coins} 枚铜钱。`;const pool=upgradePool().filter(x=>SKILLS[x.id].type==='common');const id=pool.length?pick(pool).id:null;choices=[{name:id?`买下 · ${SKILLS[id].name}`:'买一包归元散',desc:id?'花费35铜钱，学习或强化此门江湖武学。':'花费35铜钱，恢复50生命。',disabled:game.coins<35,action:()=>{game.coins-=35;if(id)gainSkill(id);else heal(50);}},{name:'讨一碗热茶',desc:'免费恢复15生命，继续赶路。',action:()=>heal(15)}];}
 showModal(`<section class="modal-panel" style="max-width:690px"><div class="modal-eyebrow">江湖奇遇 · ${e.name}</div><h2 class="modal-title">${title}</h2><p class="modal-sub">${desc}</p><div class="upgrade-grid" style="grid-template-columns:repeat(${choices.length},1fr)">${choices.map((c,i)=>`<button class="upgrade-card" data-event-choice="${i}" ${c.disabled?'disabled':''}><span class="category">萍水相逢</span><span class="big-symbol">${e.glyph}</span><b>${c.name}</b><p>${c.desc}</p></button>`).join('')}</div><div class="modal-actions"><span class="note">时间已暂停 · 每场奇遇每局只触发一次</span></div></section>`,'event');$('modal-content').querySelectorAll('[data-event-choice]').forEach(b=>b.onclick=()=>{const c=choices[+b.dataset.eventChoice];if(c.disabled)return;c.action();game.eventsDone++;closeModal();toast('一面之缘，亦是江湖',2);updateHUD();if(availableRecipes().length)openBook(true);});}
function pauseGame(){if(state!=='playing')return;showModal(`<section class="modal-panel pause-panel"><div class="modal-eyebrow">歇一歇 · 雨还未停</div><h2 class="modal-title">暂收锋芒</h2><p class="modal-sub">${game.hero.name} · ${timeText(game.time)} · 破敌 ${game.kills}<br>游戏已暂停，离开页面也会自动暂停。</p><div class="pause-menu"><button class="primary" id="resume">继续此局 <span>返回江湖 →</span></button><button class="secondary" id="pause-book">查阅武学与融合配方</button><button class="secondary" id="pause-sound">声音：${soundOn?'开启':'关闭'}</button><button class="secondary" id="quit">结束此局，返回山庄</button></div></section>`,'paused');$('resume').onclick=closeModal;$('pause-book').onclick=()=>openBook();$('pause-sound').onclick=()=>{$('pause-sound').textContent='声音：'+(toggleSound()?'开启':'关闭');};$('quit').onclick=returnHome;}
function guide(){const back=game?'paused':'home';showModal(`<section class="modal-panel"><div class="modal-eyebrow">初入江湖 · 游玩指引</div><h2 class="modal-title">十分钟，练成你的绝学</h2><p class="modal-sub">守住《归元录》，击败八分半登场的黑伞客。在十分钟之前破局，即可突围。</p><div class="guide-grid"><article><b>壹 · 行走与轻功</b><p>WASD 移动，鼠标指向决定主要攻击方向。不移动鼠标时自动索敌。空格轻功穿过敌群，可储备两次。触屏使用左摇杆与右侧按钮。</p></article><article><b>贰 · 自动出招，主动破局</b><p>兵器与武学自动攻击。Q 主动施展绝技，默认约22秒恢复。地面的朱红区域与橙色暗器是危险预警，轻功可闪避伤害。</p></article><article><b>叁 · 拾修为，学秘籍</b><p>靠近敌人掉落的青色晶石拾取修为。升级暂停时间，三选一习得武学。每局可携带三门通用武学、三门内功，两门专属武学。</p></article><article><b>肆 · 融会贯通</b><p>按 B 查看配方。兵器六重、对应专属与通用武学各三重后，消耗剑使掉落的悟道机会修成绝学。每局限一门。靠近金色奇遇按 E 交谈，或停步片刻。</p></article></div><div class="modal-actions"><span class="note">ESC 暂停 · 升级时按 1 / 2 / 3 快选 · 本地自动保存战绩</span><button class="secondary" id="guide-close">已知晓，合卷</button></div></section>`,'guide');$('guide-close').onclick=()=>{if(back==='home'){state='home';$('modal').classList.add('hidden');}else{state='playing';pauseGame();}};}
function finish(win,timeout=false){if(!game||game.finished)return;game.finished=true;state='result';keys.clear();stick.x=stick.z=0;record.runs++;if(win)record.wins++;record.best=Math.max(record.best,game.kills);saveRecord();$('damage-flash').style.opacity=0;const skills=Object.entries(game.skills).filter(([id])=>id!=='weapon').map(([id,lv])=>`${SKILLS[id].name}·${roman[lv]}重`).join('　');showModal(`<section class="modal-panel" style="max-width:720px"><div class="result-seal">${win?'破局':'再会'}</div><div class="modal-eyebrow">听雨山庄 · 此卷已毕</div><h2 class="modal-title">${win?'雨歇，归途有光':timeout?'晨钟已响，归元未竟':'胜负之外，仍有江湖'}</h2><p class="modal-sub">${win?'黑伞落地，晨色初明。你带着残卷，走出了听雨山庄。':timeout?'十分钟已过，黑伞客仍守着出口。下一次，试着更早修成融合绝学。':'你暂时倒在了雨中，但已记下几分武学真意。试着利用轻功避开包围，主动施展 Q 绝技。'}</p><div class="result-stats"><div><span>本局历时</span><b>${timeText(game.time)}</b></div><div><span>击退追兵</span><b>${game.kills}</b></div><div><span>武学境界</span><b>${game.level} 重</b></div><div><span>江湖奇遇</span><b>${game.eventsDone} 次</b></div></div><div class="build-summary">${game.hero.name} · ${game.hero.sect} · ${game.hero.weapon} ${roman[levelOf('weapon')]}重<br>融合绝学：<span style="color:var(--gold)">${game.fusion?.name||'尚未参悟'}</span><br>${skills||'此行初试锋芒'}<br>累计入局 ${record.runs} 次 · 突围 ${record.wins} 次 · 最佳破敌 ${record.best}</div><div class="modal-actions"><button class="secondary" id="result-home">重选侠客</button><button class="primary" id="retry" style="width:230px">再入江湖 <span>重试 →</span></button></div></section>`,'result');$('result-home').onclick=returnHome;$('retry').onclick=()=>startGame(selected);}
function disposeHero(){scene.remove(heroVisual.root);heroVisual.root.traverse(m=>{if(m.isMesh)m.geometry.dispose();});}
function cleanGame(){for(const p of projectiles)clearMesh(p.mesh);projectiles.length=0;for(const b of enemyShots)clearMesh(b.mesh);enemyShots.length=0;for(const a of areas)clearMesh(a.mesh,false,true);areas.length=0;for(const w of warnings)clearMesh(w.mesh,false,true);warnings.length=0;for(const p of pickups)clearMesh(p.mesh);pickups.length=0;for(const f of effects)clearMesh(f.mesh,!!f.ownGeo,true);effects.length=0;for(const e of events){scene.remove(e.root);e.root.traverse(m=>{if(m.isMesh){m.geometry.dispose();}});}events.length=0;for(const pool of Object.values(enemyPools))for(const m of [pool.body,pool.head,pool.hat,pool.arm])m.count=0;$('boss-hud').classList.add('hidden');$('toast').classList.remove('visible');$('damage-flash').style.opacity=0;}
