function returnHome(){cleanGame();game=null;state='home';$('hud').classList.add('hidden');$('modal').classList.add('hidden');$('home').classList.remove('hidden');heroVisual.root.visible=true;heroVisual.root.position.set(0,0,5);renderHome();}
