function renderHome(){const hero=HEROS[selected];$('hero-list').innerHTML=HEROS.map((h,i)=>`<button class="hero-card ${i===selected?'selected':''}" data-hero="${i}" aria-pressed="${i===selected}" style="--hero:${h.color}"><span class="hero-glyph">${h.glyph}</span><span class="hero-copy"><strong>${h.name}</strong><small>${h.sect} · ${h.weapon}</small></span><span class="hero-num">${['壹','贰','叁'][i]}</span></button>`).join('');$('hero-list').querySelectorAll('button').forEach(b=>b.onclick=()=>selectHero(+b.dataset.hero));$('hero-detail').innerHTML=`<p>${hero.desc}</p><p class="trait">${hero.trait}</p>`;$('start').innerHTML=`${hero.id==='sword'?'执剑':hero.id==='dagger'?'携刃':'撑伞'}入局 <span>启程 →</span>`;$('record').textContent=record.runs?`已入江湖 ${record.runs} 回 · 突围 ${record.wins} 回 · 最佳破敌 ${record.best}`:'初入江湖，尚无战绩';document.querySelectorAll('.sound-toggle').forEach(b=>b.textContent=soundOn?'声 音 开':'声 音 关');}
let lastSkillHTML='';function updateHUD(){if(!game)return;const p=game.player;$('hud-glyph').textContent=game.hero.glyph;$('hud-glyph').style.color=game.hero.color;$('hud-name').textContent=game.hero.name;$('hud-title').textContent=game.hero.sect+(p.shield>0?` · 护盾 ${Math.ceil(p.shield)}`:'');$('hp-label').textContent=`${Math.ceil(p.hp)} / ${maxHealth()}`;$('hp-fill').style.width=clamp(p.hp/maxHealth()*100,0,100)+'%';$('shield-fill').style.width=Math.min(100,p.shield/40*100)+'%';$('dash-label').textContent=`轻功 ${p.dash>=1?'●':'○'} ${p.dash>=2?'●':'○'}`;$('timer').textContent=timeText(game.time);$('time-fill').style.width=game.time/6+'%';$('kills').textContent=game.kills;$('level').textContent=`境界 ${game.level} 重`;$('xp-fill').style.width=game.xp/game.need*100+'%';$('phase').textContent=game.time>=510?'黑伞遮天':game.time>=420?'绝学将成':game.time>=240?'风起藏锋':game.time>=100?'群敌环伺':'山雨初至';$('fusion-status').textContent=game.fusion?`${game.fusion.name} · 已修成`:game.tokens?`悟道机会 ${game.tokens} · 按 B 查阅配方`:'武学未成 · 按 B 查阅秘籍';
 const ids=['weapon',...game.hero.exclusive,...Object.keys(game.skills).filter(id=>SKILLS[id].type==='common')];while(ids.length<6)ids.push(null);let html=ids.map(id=>{if(!id)return'<div class="skill-slot empty"><span>＋</span></div>';const d=SKILLS[id],lv=levelOf(id);return `<div class="skill-slot ${lv?'':'empty'}" style="--slot-color:${id==='weapon'?game.hero.color:d.color}" title="${skillName(id)}：${d.desc}"><span class="symbol">${id==='weapon'?game.hero.glyph:d.glyph}</span><small>${skillName(id)}</small><em>${lv?'·'.repeat(lv):'未习'}</em></div>`;}).join('');html+=`<button class="skill-slot ultimate ${p.ult<=0?'ready':''}" id="ult-button" aria-label="释放绝技 Q"><span class="cooldown" style="height:${p.ult/22*100}%"></span><span class="symbol">绝</span><small>${p.ult>0?Math.ceil(p.ult)+'秒':'Q · 就绪'}</small></button>`;if(html!==lastSkillHTML){$('skillbar').innerHTML=html;$('ult-button').onclick=ultimate;lastSkillHTML=html;}if(game.boss&&!game.boss.dead){$('boss-fill').style.width=Math.max(0,game.boss.hp/game.boss.maxHp*100)+'%';$('boss-hp-text').textContent=Math.max(0,Math.ceil(game.boss.hp/game.boss.maxHp*100))+'%';}
}
function drawMap(){if(!game)return;const ctx=$('map').getContext('2d'),w=144;ctx.clearRect(0,0,w,w);ctx.save();ctx.translate(72,72);ctx.strokeStyle='#799b7466';ctx.lineWidth=.7;ctx.strokeRect(-59,-45,118,90);for(const o of obstacles){ctx.fillStyle='#77927866';ctx.fillRect(o.x*2-o.w*2,o.z*2-o.d*2,o.w*4,o.d*4);}for(const e of events){if(e.used)continue;ctx.fillStyle='#e4c88b';ctx.fillRect(e.x*2-2,e.z*2-2,4,4);}for(const e of game.enemies){ctx.fillStyle=e.type==='boss'?'#ffc391':e.type==='elite'?'#e7a6c7':'#d28c76';ctx.beginPath();ctx.arc(e.x*2,e.z*2,e.type==='boss'?4:e.type==='elite'?2.8:1.2,0,TAU);ctx.fill();}ctx.fillStyle=game.hero.color;ctx.beginPath();ctx.arc(game.player.x*2,game.player.z*2,3,0,TAU);ctx.fill();ctx.restore();}
function toggleSound(){soundOn=!soundOn;audioInit();if(audio){audio.ctx.resume();audio.master.gain.setTargetAtTime(soundOn?.16:0,audio.ctx.currentTime,.1);}saveRecord();document.querySelectorAll('.sound-toggle').forEach(b=>b.textContent=soundOn?'声 音 开':'声 音 关');return soundOn;}
$('start').onclick=()=>startGame();$('guide-open').onclick=guide;$('pause').onclick=pauseGame;document.querySelectorAll('.sound-toggle').forEach(b=>b.onclick=toggleSound);$('touch-dash').onclick=doDash;$('touch-ult').onclick=ultimate;
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code)&&state!=='home')e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if(state==='playing')pauseGame();else if(state==='paused'||state==='book')closeModal();else if(state==='guide')$('guide-close').click();return;}if(e.code==='KeyB'&&game){if(state==='book')closeModal();else if(state==='playing'||state==='paused')openBook();return;}if(state==='upgrade'&&['Digit1','Digit2','Digit3'].includes(e.code)){const id=game.choices[+e.code.slice(-1)-1];if(id)selectUpgrade(id);return;}if(state!=='playing')return;keys.add(e.code);if(e.code==='Space')doDash();if(e.code==='KeyQ')ultimate();});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();stick.x=stick.z=0;if(state==='playing')pauseGame();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pauseGame();});
$('world').addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&state==='playing'){pointer.x=e.clientX/innerWidth*2-1;pointer.y=1-e.clientY/innerHeight*2;pointer.active=true;}});$('world').addEventListener('pointerleave',()=>pointer.active=false);
